CREATE OR REPLACE FUNCTION company_checkout_allowance_private.aggregate(p_receipts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare r jsonb; item jsonb; k text; day_key text; entry jsonb; seen jsonb:='{}';
 rows jsonb:='[]';earnings jsonb:='[]';deductions jsonb:='[]';reasons jsonb:='[]';
 grouped jsonb:='{}'; quantity numeric;amount numeric;rate numeric;
begin
 if jsonb_typeof(p_receipts) is distinct from 'array' or jsonb_array_length(p_receipts)>10000 then
  raise exception 'invalid server receipt set' using errcode='22023';end if;
 for r in select value from jsonb_array_elements(p_receipts) loop
  if jsonb_typeof(r) is distinct from 'object' or r->>'contract_version' is distinct from '1'
   or coalesce(r->>'work_date','')!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$'
   or jsonb_typeof(r->'items') is distinct from 'array' then
   raise exception 'invalid server receipt row' using errcode='22023';end if;
  perform (r->>'work_date')::date;
  for item in select value from jsonb_array_elements(r->'items') loop
   if jsonb_typeof(item) is distinct from 'object'
    or coalesce(item->>'origin','') not in ('company_legacy','company_common')
    or coalesce(item->>'id','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    or nullif(trim(item->>'name'),'') is null or length(item->>'name')>4096
    or coalesce(item->>'section','') not in ('earning','deduction') or coalesce(item->>'unit','') not in ('day','hour')
    or jsonb_typeof(item->'rate_yen') is distinct from 'number'
    or (item->>'rate_yen')::numeric<0 or (item->>'rate_yen')::numeric>2147483647
    or trunc((item->>'rate_yen')::numeric)<>(item->>'rate_yen')::numeric then
    raise exception 'invalid server receipt item' using errcode='22023';end if;
   -- ID + source identify an item. Same-day multiple site/route receipts must
   -- agree on the captured registration snapshot; choose no arbitrary winner.
   item:=jsonb_set(item,'{id}',to_jsonb((item->>'id')::uuid::text));
   k:=(item->>'origin')||':'||(item->>'id');day_key:=k||':'||(r->>'work_date');
   if seen?day_key then
    if seen->day_key is distinct from item then
     reasons:=reasons||jsonb_build_array(jsonb_build_object('code','same_day_registration_conflict','id',item->>'id','work_date',r->>'work_date'));
    end if;
    continue;
   end if;
   seen:=jsonb_set(seen,array[day_key],item,true);
   if grouped?k then
    entry:=grouped->k;
    if entry->'snapshot' is distinct from item then
     -- Mid-month configured price/label changes cannot be merged into one
     -- rate row. Keep each exact snapshot as a separate calculation row.
     k:=k||':'||encode(sha256(convert_to(item::text,'UTF8')),'hex');
    end if;
   end if;
   if item->>'unit'='day' then quantity:=1;
   else
    -- No inferred 8h/day, raw elapsed clock span, or monthly manual quantity.
    -- A future reviewed paid-work-hours source must supply this server basis.
    quantity:=null;
    reasons:=reasons||jsonb_build_array(jsonb_build_object('code','actual_work_hours_unavailable','id',item->>'id','work_date',r->>'work_date'));
   end if;
   entry:=coalesce(grouped->k,jsonb_build_object('snapshot',item,'quantity',0,'work_dates','[]'::jsonb));
   entry:=jsonb_set(entry,'{work_dates}',(entry->'work_dates')||jsonb_build_array(r->>'work_date'));
   entry:=jsonb_set(entry,'{quantity}',case when quantity is null or entry->'quantity'='null'::jsonb then 'null'::jsonb else to_jsonb((entry->>'quantity')::numeric+quantity) end);
   grouped:=jsonb_set(grouped,array[k],entry,true);
  end loop;
 end loop;
 for k,entry in select key,value from jsonb_each(grouped) order by key loop
  item:=entry->'snapshot';quantity:=(entry->>'quantity')::numeric;rate:=(item->>'rate_yen')::numeric;
  amount:=case when quantity is null then null else round(rate*quantity) end;
  if amount>2147483647 then raise exception 'company allowance exceeds range' using errcode='22023';end if;
  rows:=rows||jsonb_build_array(item||jsonb_build_object('quantity',quantity,'amount_yen',amount,'work_dates',entry->'work_dates','source','confirmed_checkout_receipt'));
  if amount is not null then
   if item->>'section'='earning' then earnings:=earnings||jsonb_build_array(jsonb_build_object('name',item->>'name','amount_yen',amount));
   else deductions:=deductions||jsonb_build_array(jsonb_build_object('name',item->>'name','amount_yen',amount));end if;
  end if;
 end loop;
 return jsonb_build_object('contract_version',1,'items',rows,'earnings',earnings,'deductions',deductions,'blocked',jsonb_array_length(reasons)>0,'reasons',reasons);
end $function$

CREATE OR REPLACE FUNCTION company_checkout_allowance_private.capture_report(rid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare report public.daily_reports%rowtype; w record; item jsonb; rows jsonb; body jsonb;
 id_value uuid; digest_value text; answer jsonb:='{}';
begin
 select * into report from public.daily_reports where id=rid;
 if not found or auth.uid() is null or private.account_access_allowed() is not true
 or not exists(select 1 from public.company_members where company_id=report.company_id and user_id=auth.uid())
 then raise exception 'company allowance report unavailable' using errcode='42501';end if;
 if not exists(select 1 from public.daily_report_workers where report_id=rid and company_allowance_selections is not null) then return answer;end if;
 if report.representative_signature_json is null or report.supervisor_signature_json is null then
  raise exception 'both report signatures required for company selections' using errcode='42501';end if;
 for w in select * from public.daily_report_workers where report_id=rid order by worker_id loop
  if w.company_allowance_selections is null then continue;end if;
  perform company_checkout_allowance_private.validate_labels(report.company_id,w.worker_id,w.allowance_label,w.company_allowance_selections,w.company_allowance_legacy_labels);
  rows:='[]';
  for item in select value from jsonb_array_elements(w.company_allowance_selections->'items') order by value->>'origin',value->>'id' loop
   rows:=rows||jsonb_build_array(company_checkout_allowance_private.registered_item(report.company_id,w.worker_id,item));
  end loop;
  body:=jsonb_build_object('contract_version',1,'work_date',report.report_date,'items',rows);
  digest_value:=encode(sha256(convert_to(body::text,'UTF8')),'hex');
  insert into company_checkout_allowance_private.receipts(company_id,worker_id,report_id,work_date,snapshot,snapshot_sha256,captured_by)
   values(report.company_id,w.worker_id,rid,report.report_date,body,digest_value,auth.uid())
   on conflict(company_id,worker_id,report_id,work_date,snapshot_sha256) do nothing;
  select id into id_value from company_checkout_allowance_private.receipts
   where company_id=report.company_id and worker_id=w.worker_id and report_id=rid
    and work_date=report.report_date and snapshot_sha256=digest_value and snapshot=body;
  if id_value is null then raise exception 'company receipt unavailable';end if;
  answer:=jsonb_set(answer,array[w.worker_id::text],to_jsonb(id_value::text),true);
 end loop;
 return answer;
end $function$

CREATE OR REPLACE FUNCTION company_checkout_allowance_private.guard_receipt_pointer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if current_user<>'postgres' and ((tg_op='INSERT' and new.company_allowance_receipt_id is not null)
 or (tg_op='UPDATE' and new.company_allowance_receipt_id is distinct from old.company_allowance_receipt_id)) then
  raise exception 'server-owned company allowance receipt' using errcode='42501';end if;
 if tg_op='UPDATE' and old.company_allowance_receipt_id is not null
 and new.company_allowance_receipt_id is not distinct from old.company_allowance_receipt_id
 and new.allowance_names is distinct from old.allowance_names then
  -- Direct clients never read the private price store through this invoker.
  if current_user<>'postgres' then
   raise exception '署名済みの会社共通手当は、この勤怠修正では削除できません。日報の修正承認後に手当を変更し、再署名してください。' using errcode='42501';
  end if;
  if exists(select 1 from company_checkout_allowance_private.receipts r
   cross join lateral jsonb_array_elements(r.snapshot->'items') item
   where r.id=old.company_allowance_receipt_id and r.company_id=old.company_id
    and r.worker_id=old.worker_id and r.report_id=old.source_report_id and r.work_date=old.work_date
    and not coalesce(item->>'name'=any(coalesce(new.allowance_names,'{}'::text[])),false)) then
   raise exception '署名済みの会社共通手当は、この勤怠修正では削除できません。日報の修正承認後に手当を変更し、再署名してください。' using errcode='22023';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.save_daily_report_destination_draft(p_report_id uuid, p_site_id uuid, p_route_assignment_id uuid, p_report_date date, p_work_description text, p_workers jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_user_id uuid:=auth.uid();
  v_company_id uuid;
  v_report_id uuid:=p_report_id;
  v_report_status text;
  v_edit_request_id uuid;
  v_worker jsonb;
  v_worker_id uuid;
  checkout_previous_choices jsonb; checkout_previous_labels jsonb;
  checkout_previous_legacy_labels jsonb; checkout_choices jsonb; checkout_legacy_labels text;
  checkout_previous_basis jsonb; checkout_prior_report_id uuid; checkout_had_choices boolean:=false;
begin
  if v_user_id is null then raise exception 'authentication required'; end if;

  select cm.company_id into v_company_id
  from public.company_members cm
  where cm.user_id=v_user_id
  limit 1;
  if v_company_id is null then raise exception 'company membership not found'; end if;

  if ((p_site_id is null) = (p_route_assignment_id is null)) then
    raise exception 'select exactly one workplace destination';
  end if;

  if p_site_id is not null and not exists(
    select 1 from public.sites s
    where s.id=p_site_id and s.company_id=v_company_id
  ) then
    raise exception 'site does not belong to company';
  end if;

  if p_route_assignment_id is not null and not exists(
    select 1 from public.route_assignments r
    where r.id=p_route_assignment_id
      and r.company_id=v_company_id
      and r.is_active=true
  ) then
    raise exception 'route does not belong to company';
  end if;

  select r.id into checkout_prior_report_id from public.daily_reports r where r.company_id=v_company_id
    and ((v_report_id is not null and r.id=v_report_id) or (v_report_id is null
      and r.site_id is not distinct from p_site_id and r.report_date=p_report_date and r.route_assignment_id is not distinct from p_route_assignment_id))
    limit 1 for update;
  checkout_previous_basis:=company_checkout_allowance_private.report_basis(checkout_prior_report_id);
  select exists(select 1 from public.daily_report_workers where report_id=checkout_prior_report_id
    and company_allowance_selections is not null) into checkout_had_choices;
  if v_report_id is not null then
    select dr.status into v_report_status
    from public.daily_reports dr
    where dr.id=v_report_id and dr.company_id=v_company_id
    for update;
    if not found then raise exception 'daily report not found'; end if;

    if v_report_status='signed' then
      select req.id into v_edit_request_id
      from public.daily_report_edit_requests req
      where req.report_id=v_report_id
        and req.requested_by=v_user_id
        and req.status='approved'
      order by req.created_at desc
      limit 1
      for update;
      if v_edit_request_id is null then
        raise exception 'signed report requires approved edit request';
      end if;
      update public.daily_report_edit_requests
      set status='used',resolved_at=coalesce(resolved_at,now())
      where id=v_edit_request_id;
    end if;

    update public.daily_reports
    set site_id=p_site_id,
        route_assignment_id=p_route_assignment_id,
        report_date=p_report_date,
        work_description=p_work_description,
        status='draft',
        signer_name=null,
        signature_json=null,
        signed_at=null,
        representative_signature_json=case when checkout_had_choices or exists(select 1 from jsonb_array_elements(coalesce(p_workers,'[]'::jsonb)) x where x?'company_allowance_selections') then representative_signature_json else null end,
        representative_signer_name=case when checkout_had_choices or exists(select 1 from jsonb_array_elements(coalesce(p_workers,'[]'::jsonb)) x where x?'company_allowance_selections') then representative_signer_name else null end,
        supervisor_signature_json=case when checkout_had_choices or exists(select 1 from jsonb_array_elements(coalesce(p_workers,'[]'::jsonb)) x where x?'company_allowance_selections') then supervisor_signature_json else null end,
        supervisor_signer_name=case when checkout_had_choices or exists(select 1 from jsonb_array_elements(coalesce(p_workers,'[]'::jsonb)) x where x?'company_allowance_selections') then supervisor_signer_name else null end,
        updated_by=v_user_id,
        updated_at=now()
    where id=v_report_id;
  else
    select dr.id,dr.status
    into v_report_id,v_report_status
    from public.daily_reports dr
    where dr.company_id=v_company_id
      and dr.report_date=p_report_date
      and dr.site_id is not distinct from p_site_id
      and dr.route_assignment_id is not distinct from p_route_assignment_id
    limit 1
    for update;

    if v_report_id is not null then
      if v_report_status='signed' then
        raise exception 'signed report requires edit approval';
      end if;
      update public.daily_reports
      set work_description=p_work_description,
          updated_by=v_user_id,
          updated_at=now()
      where id=v_report_id;
    else
      insert into public.daily_reports(
        company_id,site_id,route_assignment_id,report_date,
        work_description,status,created_by,updated_by
      )
      values(
        v_company_id,p_site_id,p_route_assignment_id,p_report_date,
        p_work_description,'draft',v_user_id,v_user_id
      )
      returning id into v_report_id;
    end if;
  end if;

  select coalesce(jsonb_object_agg(worker_id::text,company_allowance_selections),'{}'),
    coalesce(jsonb_object_agg(worker_id::text,allowance_label),'{}'),
    coalesce(jsonb_object_agg(worker_id::text,company_allowance_legacy_labels),'{}')
    into checkout_previous_choices,checkout_previous_labels,checkout_previous_legacy_labels
    from public.daily_report_workers where report_id=v_report_id;
  delete from public.daily_report_workers where report_id=v_report_id;

  for v_worker in
    select value from jsonb_array_elements(coalesce(p_workers,'[]'::jsonb))
  loop
    v_worker_id:=(v_worker->>'worker_id')::uuid;

    if nullif(v_worker->>'work_category','') is not null
       and v_worker->>'work_category' not in ('day','night','holiday','holiday_night')
    then
      raise exception 'invalid work category';
    end if;

    if (
      select count(distinct trim(v))
      from unnest(string_to_array(coalesce(v_worker->>'allowance_label',''),E'\n')) v
      where trim(v)<>''
    ) > 3 and not (v_worker?'company_allowance_selections') and nullif(checkout_previous_choices->v_worker_id::text,'null'::jsonb) is null then
      raise exception 'maximum three daily allowances';
    end if;

    if not exists(
      select 1 from public.workers w
      where w.id=v_worker_id and w.company_id=v_company_id
    ) then
      raise exception 'worker does not belong to company';
    end if;

    checkout_choices:=case when v_worker?'company_allowance_selections' then v_worker->'company_allowance_selections'
      else nullif(checkout_previous_choices->v_worker_id::text,'null'::jsonb) end;
    checkout_legacy_labels:=case when checkout_choices is null then null
      when nullif(checkout_previous_choices->v_worker_id::text,'null'::jsonb) is null then checkout_previous_labels->>v_worker_id::text
      else checkout_previous_legacy_labels->>v_worker_id::text end;
    perform company_checkout_allowance_private.validate_labels(v_company_id,v_worker_id,v_worker->>'allowance_label',checkout_choices,checkout_legacy_labels);
    insert into public.daily_report_workers(
      report_id,worker_id,overtime_hours,early_hours,night_hours,
      allowance_amount,allowance_label,work_category,company_allowance_selections,company_allowance_legacy_labels
    )
    values(
      v_report_id,v_worker_id,
      greatest(coalesce((v_worker->>'overtime_hours')::numeric,0),0),
      greatest(coalesce((v_worker->>'early_hours')::numeric,0),0),
      greatest(coalesce((v_worker->>'night_hours')::numeric,0),0),
      greatest(coalesce((v_worker->>'allowance_amount')::integer,0),0),
      nullif(trim(coalesce(v_worker->>'allowance_label','')),''),
      nullif(v_worker->>'work_category',''),checkout_choices,checkout_legacy_labels
    );
  end loop;

  if (checkout_had_choices or exists(select 1 from public.daily_report_workers where report_id=v_report_id and company_allowance_selections is not null))
    and checkout_previous_basis is distinct from company_checkout_allowance_private.report_basis(v_report_id) then
    update public.daily_reports set representative_signature_json=null,representative_signer_name=null,
      supervisor_signature_json=null,supervisor_signer_name=null where id=v_report_id;
  end if;
  return v_report_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_daily_report_draft(p_report_id uuid, p_site_id uuid, p_report_date date, p_work_description text, p_workers jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_company_id uuid;
  v_report_id uuid := p_report_id;
  v_report_status text;
  v_edit_request_id uuid;
  v_worker jsonb;
  v_worker_id uuid;
  checkout_previous_choices jsonb; checkout_previous_labels jsonb;
  checkout_previous_legacy_labels jsonb; checkout_choices jsonb; checkout_legacy_labels text;
  checkout_previous_basis jsonb; checkout_prior_report_id uuid; checkout_had_choices boolean:=false;
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  select cm.company_id
  into v_company_id
  from public.company_members cm
  where cm.user_id = v_user_id
  limit 1;

  if v_company_id is null then
    raise exception 'company membership not found';
  end if;

  if not exists (
    select 1 from public.sites s
    where s.id = p_site_id
      and s.company_id = v_company_id
  ) then
    raise exception 'site does not belong to company';
  end if;

  select r.id into checkout_prior_report_id from public.daily_reports r where r.company_id=v_company_id
    and ((v_report_id is not null and r.id=v_report_id) or (v_report_id is null
      and r.site_id is not distinct from p_site_id and r.report_date=p_report_date and true))
    limit 1 for update;
  checkout_previous_basis:=company_checkout_allowance_private.report_basis(checkout_prior_report_id);
  select exists(select 1 from public.daily_report_workers where report_id=checkout_prior_report_id
    and company_allowance_selections is not null) into checkout_had_choices;
  if v_report_id is not null then
    select dr.status
    into v_report_status
    from public.daily_reports dr
    where dr.id = v_report_id
      and dr.company_id = v_company_id
    for update;

    if not found then
      raise exception 'daily report not found';
    end if;

    if v_report_status = 'signed' then
      select req.id
      into v_edit_request_id
      from public.daily_report_edit_requests req
      where req.report_id = v_report_id
        and req.requested_by = v_user_id
        and req.status = 'approved'
      order by req.created_at desc
      limit 1
      for update;

      if v_edit_request_id is null then
        raise exception 'signed report requires approved edit request';
      end if;

      update public.daily_report_edit_requests
      set status = 'used',
          resolved_at = coalesce(resolved_at, now())
      where id = v_edit_request_id;
    end if;

    update public.daily_reports
    set site_id = p_site_id,
        report_date = p_report_date,
        work_description = p_work_description,
        status = 'draft',
        signer_name = null,
        signature_json = null,
        signed_at = null,
        updated_by = v_user_id,
        updated_at = now()
    where id = v_report_id;
  else
    insert into public.daily_reports(
      company_id,
      site_id,
      report_date,
      work_description,
      status,
      created_by,
      updated_by
    )
    values(
      v_company_id,
      p_site_id,
      p_report_date,
      p_work_description,
      'draft',
      v_user_id,
      v_user_id
    )
    on conflict(company_id, site_id, report_date) do update
    set work_description = excluded.work_description,
        updated_by = v_user_id,
        updated_at = now()
    returning id, status into v_report_id, v_report_status;

    if v_report_status = 'signed' then
      raise exception 'signed report requires edit approval';
    end if;
  end if;

  select coalesce(jsonb_object_agg(worker_id::text,company_allowance_selections),'{}'),
    coalesce(jsonb_object_agg(worker_id::text,allowance_label),'{}'),
    coalesce(jsonb_object_agg(worker_id::text,company_allowance_legacy_labels),'{}')
    into checkout_previous_choices,checkout_previous_labels,checkout_previous_legacy_labels
    from public.daily_report_workers where report_id=v_report_id;
  delete from public.daily_report_workers where report_id=v_report_id;

  for v_worker in
    select value from jsonb_array_elements(coalesce(p_workers, '[]'::jsonb))
  loop
    v_worker_id := (v_worker ->> 'worker_id')::uuid;
    if nullif(v_worker->>'work_category','') is not null and
       v_worker->>'work_category' not in ('day','night','holiday','holiday_night') then
      raise exception 'invalid work category';
    end if;
    if (select count(distinct trim(v)) from unnest(string_to_array(coalesce(v_worker->>'allowance_label',''), E'\n')) v where trim(v)<>'') > 3 and not (v_worker?'company_allowance_selections') and nullif(checkout_previous_choices->v_worker_id::text,'null'::jsonb) is null then
      raise exception 'maximum three daily allowances';
    end if;


    if not exists (
      select 1 from public.workers w
      where w.id = v_worker_id
        and w.company_id = v_company_id
    ) then
      raise exception 'worker does not belong to company';
    end if;

    checkout_choices:=case when v_worker?'company_allowance_selections' then v_worker->'company_allowance_selections'
      else nullif(checkout_previous_choices->v_worker_id::text,'null'::jsonb) end;
    checkout_legacy_labels:=case when checkout_choices is null then null
      when nullif(checkout_previous_choices->v_worker_id::text,'null'::jsonb) is null then checkout_previous_labels->>v_worker_id::text
      else checkout_previous_legacy_labels->>v_worker_id::text end;
    perform company_checkout_allowance_private.validate_labels(v_company_id,v_worker_id,v_worker->>'allowance_label',checkout_choices,checkout_legacy_labels);
    insert into public.daily_report_workers(
      report_id,
      worker_id,
      overtime_hours,
      early_hours,
      night_hours,
      allowance_amount,
      allowance_label,
      work_category,company_allowance_selections,company_allowance_legacy_labels
    )
    values(
      v_report_id,
      v_worker_id,
      greatest(coalesce((v_worker ->> 'overtime_hours')::numeric, 0), 0),
      greatest(coalesce((v_worker ->> 'early_hours')::numeric, 0), 0),
      greatest(coalesce((v_worker ->> 'night_hours')::numeric, 0), 0),
      greatest(coalesce((v_worker ->> 'allowance_amount')::integer, 0), 0),
      nullif(trim(coalesce(v_worker ->> 'allowance_label', '')), ''),
      nullif(v_worker ->> 'work_category', ''),checkout_choices,checkout_legacy_labels
    );
  end loop;

  if (checkout_had_choices or exists(select 1 from public.daily_report_workers where report_id=v_report_id and company_allowance_selections is not null))
    and checkout_previous_basis is distinct from company_checkout_allowance_private.report_basis(v_report_id) then
    update public.daily_reports set representative_signature_json=null,representative_signer_name=null,
      supervisor_signature_json=null,supervisor_signer_name=null where id=v_report_id;
  end if;
  return v_report_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.sign_daily_report(p_report_id uuid, p_signer_name text, p_signature_json jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare scope_before jsonb; checkout_receipts jsonb;
  v_user_id uuid:=auth.uid();
  v_company_id uuid;
  v_site_id uuid;
  v_route_id uuid;
  v_date date;
  v_detail record;
  v_entry_id uuid;
begin
  if v_user_id is null then raise exception 'authentication required'; end if;

  if not exists(select 1 from public.daily_reports dr join public.company_members cm on cm.company_id=dr.company_id and cm.user_id=auth.uid() where dr.id=p_report_id) then raise exception 'daily report not found'; end if;
  scope_before:=payroll_scope_private.report_sources(p_report_id);
  perform payroll_scope_private.lock_scopes(scope_before->'scopes');
  select dr.company_id,dr.site_id,dr.route_assignment_id,dr.report_date
  into v_company_id,v_site_id,v_route_id,v_date
  from public.daily_reports dr
  join public.company_members cm
    on cm.company_id=dr.company_id and cm.user_id=v_user_id
  where dr.id=p_report_id
  for update;

  if v_company_id is null then raise exception 'daily report not found'; end if;
  perform 1 from public.daily_report_workers where report_id=p_report_id order by worker_id for share;
  if payroll_scope_private.report_sources(p_report_id) is distinct from scope_before then raise exception 'daily report payroll scope changed' using errcode='40001'; end if;

  if nullif(trim(coalesce(p_signer_name,'')),'') is null then
    raise exception 'signer name is required';
  end if;
  if p_signature_json is null or p_signature_json='[]'::jsonb then
    raise exception 'signature is required';
  end if;

  checkout_receipts:=company_checkout_allowance_private.capture_report(p_report_id);

  update public.daily_reports
  set status='signed',
      signer_name=trim(p_signer_name),
      signature_json=p_signature_json,
      signed_at=now(),
      updated_by=v_user_id,
      updated_at=now()
  where id=p_report_id;

  delete from public.attendance_entries ae
  where ae.source_report_id=p_report_id
    and (
      ae.site_id is distinct from v_site_id
      or ae.route_assignment_id is distinct from v_route_id
      or ae.work_date<>v_date
      or not exists(
        select 1 from public.daily_report_workers rw
        where rw.report_id=p_report_id and rw.worker_id=ae.worker_id
      )
    );

  for v_detail in
    select * from public.daily_report_workers
    where report_id=p_report_id
  loop
    select ae.id into v_entry_id
    from public.attendance_entries ae
    where ae.company_id=v_company_id
      and ae.worker_id=v_detail.worker_id
      and ae.site_id is not distinct from v_site_id
      and ae.route_assignment_id is not distinct from v_route_id
      and ae.work_date=v_date
      and ae.source_report_id=p_report_id
    order by ae.created_at
    limit 1;

    if v_entry_id is null then
      if exists(
        select 1 from public.attendance_entries ae
        where ae.company_id=v_company_id
          and ae.worker_id=v_detail.worker_id
          and ae.site_id is not distinct from v_site_id
          and ae.route_assignment_id is not distinct from v_route_id
          and ae.work_date=v_date
          and ae.source_report_id is distinct from p_report_id
      ) then
        raise exception '同じ日・勤務先の別の出勤記録があります。管理者が確認してください。';
      end if;

      insert into public.attendance_entries(
        company_id,work_date,worker_id,site_id,route_assignment_id,
        base_man_days,overtime_hours,early_hours,night_hours,
        allowance_amount,notes,work_category,allowance_names,
        source_report_id,company_allowance_receipt_id,created_by,updated_by
      )
      values(
        v_company_id,v_date,v_detail.worker_id,v_site_id,v_route_id,
        1,v_detail.overtime_hours,v_detail.early_hours,v_detail.night_hours,
        v_detail.allowance_amount,v_detail.allowance_label,v_detail.work_category,
        array(
          select distinct trim(v)
          from unnest(string_to_array(coalesce(v_detail.allowance_label,''),E'\n')) v
          where trim(v)<>''
        ),
        p_report_id,(checkout_receipts->>v_detail.worker_id::text)::uuid,v_user_id,v_user_id
      );
    else
      update public.attendance_entries
      set base_man_days=1,
          overtime_hours=v_detail.overtime_hours,
          early_hours=v_detail.early_hours,
          night_hours=v_detail.night_hours,
          allowance_amount=v_detail.allowance_amount,
          notes=v_detail.allowance_label,
          work_category=v_detail.work_category,
          allowance_names=array(
            select distinct trim(v)
            from unnest(string_to_array(coalesce(v_detail.allowance_label,''),E'\n')) v
            where trim(v)<>''
          ),
          source_report_id=p_report_id,
          company_allowance_receipt_id=(checkout_receipts->>v_detail.worker_id::text)::uuid,
          updated_by=v_user_id,
          updated_at=now()
      where id=v_entry_id and source_report_id=p_report_id;
    end if;

    v_entry_id:=null;
  end loop;
end;
$function$
